#!/usr/bin/env python3
import json, pathlib, datetime
ROOT=pathlib.Path(__file__).resolve().parents[1]
rows=[
 {'id':'B-RUNTIME-TARGET','requirement':'Fresh target runtime state','current':'Authenticated live target capture; BDF and UUID match; driver/GSP 615.71.09; package verifier PASS','authoritative_close':'timestamped target package from BDF 0000:03:00.0 verified by verify_target_package.py','evidence':['evidence/target_live_20261104/target_package.json','TARGET_LIVE_FINDINGS.md'],'status':'CLOSED'},
 {'id':'B-EFFECTIVE-REGISTRY','requirement':'Effective RmDisableDisplay/RMRunFub/RMFubUseCaseMask and related NVKV values','current':'Static ingestion path recovered; live values absent','authoritative_close':'target package containing readable registry/NVKV source with command and timestamp','evidence':['GSP_DISPLAY_CONFIG_DATAFLOW.md','HOST_REGISTRY_PRODUCER.md'],'status':'OPEN'},
 {'id':'B-FUNCTIONAL-DISPLAY','requirement':'Display capability, KMS and headless graphics correctness','current':'Live CUDA/WMMA/cuBLAS correctness PASS; NVIDIA EGL initializes with process-scoped vendor manifest; pixel readback pending; Vulkan NVIDIA ICD initialization fails; DRM user access denied','authoritative_close':'fresh display/KMS plus EGL/OpenGL/Vulkan/CUDA results tied to target UUID','evidence':['TARGET_LIVE_FINDINGS.md','evidence/target_live_20261104/egl_nvidia_only.json','evidence/target_live_20261104/vulkan_nvidia_only.json','evidence/target_live_20261104/drm_access_vulkan_inventory.json'],'status':'OPEN'},
 {'id':'B-REFERENCE-ROM','requirement':'Independent revision-matched TU106 reference ROM','current':'16 unique local ROM contents lack authenticated provenance; DCB tables identical','authoritative_close':'externally sourced ROM with chain-of-custody and exact SKU/revision metadata','evidence':['evidence/rom_inventory.json','evidence/rom_dcb_all_inventory.json'],'status':'OPEN'},
 {'id':'B-PCB-ROUTING','requirement':'CG161P REV2 physical routing and package/connector evidence','current':'Only supplied identifiers, static DCB and secondary prose; no authenticated board material','authoritative_close':'authenticated PCB photos plus schematic/boardview or documented continuity','evidence':['DISPLAY_PCB_EVIDENCE.md','evidence/pcb_evidence_provenance.json'],'status':'OPEN'},
]
out={'schema':'phase21-blocker-register-v1','generated_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'rows':rows,'rule':'OPEN means the requirement is not complete; static or historical evidence cannot close a current-target blocker.'}
(ROOT/'evidence/blocker_register.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
print('blocker register:',sum(row['status']=='OPEN' for row in rows),'OPEN,',sum(row['status']=='CLOSED' for row in rows),'CLOSED')
